import React from 'react';
import { createRoot } from 'react-dom/client';
import { RouterProvider, createHashRouter, useNavigate } from 'react-router-dom';
// import Signin from './Pages/Signin';
import Home from './Pages/Home';
import App from "./App"
import {UserData, AgentEdit, AgentsData} from "./Backend/AgentData_UserData"
import { ThemeProvider, createTheme } from '@mui/material';
import CssBaseline from '@mui/material/CssBaseline';
import AgentsPage from './Pages/AgentPage';

// const Home: React.FC = () => <h1>Home</h1>;

const agentsData = new AgentsData();
const agentEdit = new AgentEdit();
const userData = new UserData();

const darkTheme = createTheme({
  palette: {
      mode: 'dark',
      background: {
          default: '#070C12',
      },
  },
});

var Route = [
  {
    path: '/',
    element: <App agentData={agentsData} userData={userData}/>, // Render Signin component for path '/'
  },
  {
    path: '/home',
    element: <ThemeProvider theme={darkTheme}><CssBaseline /><Home agentsData={agentsData}/></ThemeProvider>, // Render Home component for path '/home'
  },
  // {
  //   path: '/home/',
  //   element: <ThemeProvider theme={darkTheme}><CssBaseline /><AgentsPage agent_data_i={agentsData} agent_edit={agentEdit} agent_data={agentsData} /></ThemeProvider>, 
  // },
];

